196	    /**
197	     * The owner's age band derived from {@link #birthDate} relative to the
198	     * {@link #registrationDate}: {@code 'MINOR'} when under 18, {@code 'ADULT'} from 18 to 64,
199	     * and {@code 'SENIOR'} at 65 or older. Returns {@code null} when no birthDate is set. The age
200	     * is the number of complete years between the birthDate and the registrationDate (or the
201	     * current date when the registrationDate is not yet set).
202	     */
203	    public String getAgeBand() {
204	        if (this.birthDate == null) {
205	            return null;
206	        }
207	        LocalDate reference = this.registrationDate != null ? this.registrationDate : LocalDate.now();
208	        int years = Period.between(this.birthDate, reference).getYears();
209	        if (years < 18) {
210	            return "MINOR";
211	        }
212	        if (years < 65) {
213	            return "ADULT";
214	        }
215	        return "SENIOR";
216	    }
