591	    /**
592	     * Whether this owner belongs to a household of three or more: its {@link #getHouseholdSize()
593	     * householdSize} is {@code 3} or greater. A {@code null} householdSize, meaning the size is not
594	     * known, is treated as not a large household.
595	     */
596	    private boolean hasLargeHousehold() {
597	        return this.householdSize != null && this.householdSize >= 3;
598	    }
599	
600	    /**
601	     * Whether this owner has an email on record: a non-{@code null}, non-empty {@link #getEmail()
602	     * email}. This is the single source of the "has an email" test, shared by every rule keyed by
603	     * email presence so the check is never re-derived elsewhere.
604	     */
605	    private boolean hasEmail() {
606	        return this.email != null && !this.email.isEmpty();
607	    }
608	
609	    /**
610	     * Whether this owner's name is unique in the clinic: its {@link #getNamesakeCount() namesakeCount}
611	     * is {@code 0} (no other owner shares the name). A {@code null} namesakeCount, meaning the count is
612	     * not known, is treated as not unique.
613	     */
614	    private boolean hasNoNamesakes() {
615	        return this.namesakeCount != null && this.namesakeCount == 0;
616	    }
617	
618	    /**
619	     * Whether this owner's {@linkplain #getTenureFiscalYears() tenure} spans at least one elapsed
620	     * fiscal year. A newly created owner (zero elapsed fiscal years) does not qualify; the threshold
621	     * is crossed only once at least one fiscal-year boundary has passed since registration.
622	     */
623	    private boolean hasQualifyingTenure() {
624	        return this.getTenureFiscalYears() >= 1;
625	    }
626	
627	    /**
628	     * The owner's tenure in elapsed fiscal years: the number of fiscal-year boundaries between the
629	     * {@linkplain #fiscalYearOf(LocalDate) fiscal year} of the {@link #registrationDate} and the
630	     * fiscal year of the current date, or {@code 0} when the registrationDate is not yet set (a newly
631	     * created owner has zero tenure). Never negative.
632	     */
633	    public long getTenureFiscalYears() {
634	        if (this.registrationDate == null) {
635	            return 0;
636	        }
637	        return Math.max(0, fiscalYearOf(LocalDate.now()) - fiscalYearOf(this.registrationDate));
638	    }
639	
640	    /**
641	     * The owner's preferred contact channel: {@code 'EMAIL'} when an email is present,
642	     * otherwise {@code 'PHONE'}.
643	     */
644	    public String getContactPreference() {
645	        return hasEmail() ? "EMAIL" : "PHONE";
646	    }
647	
648	    /**
649	     * The owner's stored E.164 {@linkplain #getTelephone() telephone} formatted for humans:
650	     * a {@code '+'}, the {@linkplain #countryCodeOf(String) country calling code}, a space, and
651	     * the national digits grouped into threes from the left separated by spaces,
652	     * e.g. {@code '+61412345678'} -> {@code '+61 412 345 678'}. The raw {@link #getTelephone()
653	     * telephone} stays in E.164. Returns the telephone unchanged when it is {@code null}, not in
654	     * E.164 form, or carries no known country code.
655	     */
656	    public String getTelephoneDisplay() {
657	        if (this.telephone == null || !this.telephone.startsWith("+")) {
658	            return this.telephone;
659	        }
660	        String digits = this.telephone.substring(1);
661	        String countryCode = countryCodeOf(digits);
662	        if (countryCode == null) {
663	            return this.telephone;
664	        }
665	        String national = digits.substring(countryCode.length());
666	        StringBuilder groups = new StringBuilder();
667	        for (int i = 0; i < national.length(); i += 3) {
668	            if (groups.length() > 0) {
669	                groups.append(' ');
670	            }
671	            groups.append(national, i, Math.min(i + 3, national.length()));
672	        }
673	        return "+" + countryCode + " " + groups;
674	    }
675	
676	    /**
677	     * The owner's identity key: the single derived value used for duplicate detection.
678	     * It joins the normalized (E.164) telephone, the email (already lower-cased, or the
679	     * empty string when absent) and the householdId (or the empty string when the owner
680	     * has no household) with {@code '|'}, e.g. {@code '+61412345678|jane@example.test|3C1A9F2B7D4E'}.
681	     * Two owners are duplicates only when their whole identity keys are equal.
682	     */
683	    public String getIdentityKey() {
684	        String telephonePart = this.telephone == null ? "" : this.telephone;
685	        String emailPart = this.email == null ? "" : this.email;
686	        String householdPart = this.householdId == null ? "" : this.householdId;
687	        return telephonePart + "|" + emailPart + "|" + householdPart;
688	    }
689	
690	    protected Set<Pet> getPetsInternal() {
691	        if (this.pets == null) {
692	            this.pets = new HashSet<>();
693	        }
694	        return this.pets;
695	    }
696	
697	    protected void setPetsInternal(Set<Pet> pets) {
698	        this.pets = pets;
699	    }
700	
701	    public List<Pet> getPets() {
702	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
703	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
704	        return Collections.unmodifiableList(sortedPets);
705	    }
706	
707	    public void setPets(List<Pet> pets) {
708	        this.pets = new HashSet<>(pets);
709	    }
710	
711	    public void addPet(Pet pet) {
712	        getPetsInternal().add(pet);
713	        pet.setOwner(this);
714	    }
715	
716	    /**
717	     * Return the Pet with the given name, or null if none found for this Owner.
718	     *
719	     * @param name to test
720	     * @return true if pet name is already in use
721	     */
722	    public Pet getPet(String name) {
723	        return getPet(name, false);
724	    }
725	
726	    /**
727	     * Return the Pet with the given name, or null if none found for this Owner.
728	     *
729	     * @param name to test
730	     * @return true if pet name is already in use
731	     */
732	    public Pet getPet(String name, boolean ignoreNew) {
733	        name = name.toLowerCase();
734	        for (Pet pet : getPetsInternal()) {
735	            if (!ignoreNew || !pet.isNew()) {
736	                String compName = pet.getName();
737	                compName = compName.toLowerCase();
738	                if (compName.equals(name)) {
739	                    return pet;
740	                }
741	            }
742	        }
743	        return null;
744	    }
745	
746	    public Pet getPet(Integer petId) {
747	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
748	    }
749	
750	    @Override
751	    public String toString() {
752	        return new ToStringCreator(this)
753	
754	            .append("id", this.getId())
755	            .append("new", this.isNew())
756	            .append("lastName", this.getLastName())
757	            .append("firstName", this.getFirstName())
758	            .append("address", this.address)
759	            .append("city", this.city)
760	            .append("telephone", this.telephone)
761	            .append("email", this.email)
762	            .toString();
763	    }
764	}
