51	import org.springframework.samples.petclinic.service.ClinicService;
52	import org.springframework.security.access.prepost.PreAuthorize;
53	import org.springframework.web.bind.annotation.CrossOrigin;
54	import org.springframework.web.bind.annotation.RequestMapping;
55	import org.springframework.web.bind.annotation.RestController;
56	import org.springframework.web.context.request.RequestContextHolder;
57	import org.springframework.web.context.request.ServletRequestAttributes;
58	import org.springframework.web.util.UriComponentsBuilder;
59	
60	import jakarta.transaction.Transactional;
61	
62	/**
63	 * @author Vitaliy Fedoriv
64	 */
65	
66	@RestController
67	@CrossOrigin(exposedHeaders = "errors, content-type")
68	@RequestMapping("/api")
69	public class OwnerRestControllerV1 implements OwnersApi {
70	
71	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
72	
73	    /**
74	     * The HTTP request header a client may send to make a create idempotent. When a create repeats
75	     * with a key already seen, the originally created owner is returned instead of a duplicate.
76	     */
77	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
78	
79	    /**
80	     * Remembers, per {@link #IDEMPOTENCY_KEY_HEADER Idempotency-Key}, the id of the owner that key's
81	     * first successful create produced, so a repeat of that create can return the same owner rather
82	     * than creating a duplicate.
83	     */
84	    private final Map<String, Integer> idempotentCreates = new ConcurrentHashMap<>();
85	
86	    /**
87	     * Fixed public-holiday calendar. A registration date that lands on one of these dates is rolled
88	     * forward to the next non-holiday business day, in the same way weekends are.
89	     */
90	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
91	        LocalDate.of(2026, 1, 1),
92	        LocalDate.of(2026, 1, 26),
93	        LocalDate.of(2026, 4, 25),
94	        LocalDate.of(2026, 12, 25),
95	        LocalDate.of(2026, 12, 28));
96	
97	    private final ClinicService clinicService;
98	
99	    private final OwnerMapper ownerMapper;
100	
101	    private final PetMapper petMapper;
102	
103	    private final VisitMapper visitMapper;
104	
105	    private final AddressNormalizer addressNormalizer;
106	
107	    public OwnerRestControllerV1(ClinicService clinicService,
108	                                 OwnerMapper ownerMapper,
109	                                 PetMapper petMapper,
110	                                 VisitMapper visitMapper,
111	                                 AddressNormalizer addressNormalizer) {
112	        this.clinicService = clinicService;
113	        this.ownerMapper = ownerMapper;
114	        this.petMapper = petMapper;
115	        this.visitMapper = visitMapper;
116	        this.addressNormalizer = addressNormalizer;
117	    }
118	
119	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
120	    @Override
121	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
122	        Collection<Owner> owners;
123	        if (lastName != null) {
124	            owners = this.clinicService.findOwnerByLastName(lastName);
125	        } else {
126	            owners = this.clinicService.findAllOwners();
127	        }
128	        if (owners.isEmpty()) {
129	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
130	        }
131	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
132	    }
133	
134	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
135	    @Override
136	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
137	        Owner owner = this.clinicService.findOwnerById(ownerId);
138	        if (owner == null) {
139	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
140	        }
141	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
142	    }
143	
144	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
145	    @Override
146	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
147	        String idempotencyKey = currentIdempotencyKey();
148	        if (idempotencyKey != null) {
149	            Integer existingId = idempotentCreates.get(idempotencyKey);
150	            if (existingId != null) {
151	                Owner existing = this.clinicService.findOwnerById(existingId);
152	                if (existing != null) {
153	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(existing), HttpStatus.OK);
154	                }
155	            }
156	        }
157	
158	        ResponseEntity<OwnerDto> response = createOwner(ownerFieldsDto);
159	
160	        if (idempotencyKey != null && response.getStatusCode() == HttpStatus.CREATED
161	            && response.getBody() != null && response.getBody().getId() != null) {
162	            idempotentCreates.put(idempotencyKey, response.getBody().getId());
163	        }
164	        return response;
165	    }
166	
167	    /**
168	     * The non-blank {@link #IDEMPOTENCY_KEY_HEADER Idempotency-Key} header of the request currently
169	     * being handled, or {@code null} when the request carries no such header (or no request is bound
170	     * to the current thread). Used to make a repeated create return the originally created owner.
171	     */
172	    private String currentIdempotencyKey() {
173	        if (!(RequestContextHolder.getRequestAttributes() instanceof ServletRequestAttributes attributes)) {
174	            return null;
175	        }
176	        String key = attributes.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
177	        return (key == null || key.isBlank()) ? null : key;
178	    }
179	
180	    /**
181	     * Run the full owner-creation pipeline for a submitted {@link OwnerFieldsDto} and build its
182	     * response. The submitted fields are mapped to an {@link Owner}, which is
183	     * {@link #normalizeAndValidate(Owner) normalized and validated}, checked against the
184	     * {@link #isDailyLimitReached(LocalDate) daily creation limit}, {@link #assignHousehold(Owner)
185	     * assigned its household} and screened for {@link #checkForConflicts(Owner) conflicts};
186	     * a surviving owner then has its {@link #assignDerivedAttributes(Owner, boolean) derived
187	     * attributes} assigned, is persisted and audited. Returns the {@link #created(Owner) 201 Created}
188	     * response for the persisted owner, or the {@link HttpStatus} the create must fail with
189	     * ({@code 400 Bad Request}, {@code 429 Too Many Requests} or {@code 409 Conflict}) when the owner
190	     * cannot be created.
191	     */
192	    private ResponseEntity<OwnerDto> createOwner(OwnerFieldsDto ownerFieldsDto) {
193	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
194	
195	        HttpStatus invalid = normalizeAndValidate(owner);
196	        if (invalid != null) {
197	            return new ResponseEntity<>(invalid);
198	        }
199	        if (isDailyLimitReached(owner.getRegistrationDate())) {
200	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
201	        }
202	
203	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
204	        assignHousehold(owner);
205	
206	        HttpStatus conflict = checkForConflicts(owner);
207	        if (conflict != null) {
208	            return new ResponseEntity<>(conflict);
209	        }
210	
211	        assignDerivedAttributes(owner, sharesHousehold);
212	        this.clinicService.saveOwner(owner);
213	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
214	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
215	            owner.getMembershipLevel(), owner.getMembershipNumber());
216	        return created(owner);
217	    }
218	
219	    /**
220	     * Bring a freshly mapped owner into its canonical, valid form, or report the reason it must be
221	     * rejected. The owner's {@link #normalizeAddress(Owner) address is normalized} (a missing address
222	     * is rejected), its telephone is converted to E.164 (an unconvertible number is rejected), its
223	     * postcode is checked against its city's region, a registration date in the future is rejected,
224	     * and the effective registration date (the supplied one, or today when none was given) is rolled
225	     * onto a business day and stored back on the owner. Returns {@code null} once the owner is valid
226	     * and normalized, or the {@link HttpStatus} the create must fail with ({@code 400 Bad Request})
227	     * otherwise.
228	     */
229	    private HttpStatus normalizeAndValidate(Owner owner) {
230	        if (!normalizeAddress(owner)) {
231	            return HttpStatus.BAD_REQUEST;
232	        }
233	        String telephone = toE164(owner.getTelephone());
234	        if (telephone == null) {
235	            return HttpStatus.BAD_REQUEST;
236	        }
237	        owner.setTelephone(telephone);
238	        if (isDisposableEmail(owner.getEmail())) {
239	            return HttpStatus.BAD_REQUEST;
240	        }
241	        if (!owner.isPostcodeValid()) {
242	            return HttpStatus.BAD_REQUEST;
243	        }
244	        if (owner.getRegistrationDate() != null
245	            && owner.getRegistrationDate().isAfter(LocalDate.now())) {
246	            return HttpStatus.BAD_REQUEST;
247	        }
248	        LocalDate effectiveDate = owner.getRegistrationDate() != null
249	            ? owner.getRegistrationDate() : LocalDate.now();
250	        owner.setRegistrationDate(toBusinessDay(effectiveDate));
251	        return null;
252	    }
253	
254	    /**
255	     * Normalize the owner's supplied address into its canonical stored form and report whether an
256	     * address was supplied at all. The owner may supply its address either as the structured
257	     * {@code addressLine1}/{@code addressLine2} fields or as the flat {@code address} field, which is
258	     * kept for backward compatibility; the structured form is preferred whenever a non-blank
259	     * {@code addressLine1} is present. Each supplied field is run through the {@link AddressNormalizer}
260	     * (trimmed, whitespace-collapsed, upper-cased, common street-type abbreviations expanded). When the
261	     * structured form is used, the normalized {@code addressLine1} and {@code addressLine2} are stored
262	     * back and the composed {@link Owner#getAddress() address} becomes the normalized
263	     * {@code addressLine1} with a single space and the normalized {@code addressLine2} appended when an
264	     * {@code addressLine2} is present; when the flat form is used, the normalized flat address is
265	     * stored and no structured lines are kept. Returns {@code true} once a non-blank address has been
266	     * normalized and stored, or {@code false} when neither form supplied an address, in which case the
267	     * create must be rejected with {@code 400 Bad Request}.
268	     */
269	    private boolean normalizeAddress(Owner owner) {
270	        String line1 = addressNormalizer.normalize(owner.getAddressLine1());
271	        if (!line1.isEmpty()) {
272	            String line2 = addressNormalizer.normalize(owner.getAddressLine2());
273	            owner.setAddressLine1(line1);
274	            owner.setAddressLine2(line2.isEmpty() ? null : line2);
275	            owner.setAddress(line2.isEmpty() ? line1 : line1 + " " + line2);
276	            return true;
277	        }
278	        String address = addressNormalizer.normalize(owner.getAddress());
279	        if (address.isEmpty()) {
280	            return false;
281	        }
282	        owner.setAddressLine1(null);
283	        owner.setAddressLine2(null);
284	        owner.setAddress(address);
285	        return true;
286	    }
287	
288	    /**
289	     * The set of disposable (throwaway) email domains that an owner's email may not use. An owner
290	     * whose email is hosted on one of these domains is rejected with {@code 400 Bad Request}.
291	     */
292	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
293	        "mailinator.com", "tempmail.com", "guerrillamail.com");
294	
295	    /**
296	     * Whether the given email is hosted on a {@linkplain #DISPOSABLE_EMAIL_DOMAINS disposable}
297	     * domain. The email is optional, so a {@code null} or empty email is not disposable; otherwise
298	     * the domain (the part after the last {@code '@'}, compared case-insensitively) is matched
299	     * against the blocklist.
300	     */
301	    private boolean isDisposableEmail(String email) {
302	        if (email == null || email.isEmpty()) {
303	            return false;
304	        }
305	        int at = email.lastIndexOf('@');
306	        if (at < 0) {
307	            return false;
308	        }
309	        String domain = email.substring(at + 1).toLowerCase();
310	        return DISPOSABLE_EMAIL_DOMAINS.contains(domain);
311	    }
312	
313	    /**
314	     * Assign the owner its household link. The {@link #householdId(Owner) householdId} is computed
315	     * deterministically from the owner's lastName and postcode, so every owner sharing that
316	     * lastName and postcode is assigned the same value automatically, independent of whether the
317	     * owner declares it shares a household. The link is assigned before the
318	     * {@link #checkForConflicts(Owner) conflict checks} because it is part of the owner's
319	     * {@link Owner#getIdentityKey() identity} and feeds its {@link #householdSize(String) household
320	     * size}.
321	     */
322	    private void assignHousehold(Owner owner) {
323	        owner.setHouseholdId(householdId(owner));
324	    }
325	
326	    /**
327	     * Whether the owner clashes with an owner that already exists, and the {@link HttpStatus} the
328	     * create must fail with when it does. An owner is rejected with {@code 409 Conflict} only when
329	     * its {@link #isCityAtCapacity(String) city is already at capacity}. Sharing a household with
330	     * existing members is not a conflict: the owner is admitted as a household member and has its
331	     * {@linkplain #membershipLevel(Owner) membership level} capped at one above the household
332	     * maximum. Returns {@code null} when the owner clashes with nothing and may be created.
333	     */
334	    private HttpStatus checkForConflicts(Owner owner) {
335	        if (isCityAtCapacity(owner.getCity())) {
336	            return HttpStatus.CONFLICT;
337	        }
338	        return null;
339	    }
340	
341	    /**
342	     * Build the {@code 201 Created} response for a persisted owner: its {@link OwnerDto} body and a
343	     * {@code Location} header pointing at {@code /api/owners/{id}}.
344	     */
345	    private ResponseEntity<OwnerDto> created(Owner owner) {
346	        HttpHeaders headers = new HttpHeaders();
347	        headers.setLocation(UriComponentsBuilder.newInstance()
348	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
349	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), headers, HttpStatus.CREATED);
350	    }
351	
352	    /**
353	     * Assign the attributes that are derived once, at creation time, and stored on the owner: its
354	     * {@link #customerCode(Owner) customerCode}, {@link #namesakeCount(String, String) namesakeCount},
355	     * {@link #isBulkSignup(LocalDate) bulk-signup warning}, {@link #householdSize(String)
356	     * householdSize} and {@link #membershipLevel(Owner) membershipLevel}. Each is computed from the
357	     * owner's own fields together with the owners already present, so this runs after the owner has
358	     * been validated and has passed the duplicate and capacity checks, and immediately before it is
359	     * persisted.
360	     */
361	    private void assignDerivedAttributes(Owner owner, boolean sharesHousehold) {
362	        owner.setCustomerCode(customerCode(owner));
363	        owner.setNamesakeCount(namesakeCount(owner.getFirstName(), owner.getLastName()));
364	        owner.setBulkSignupWarning(isBulkSignup(owner.getRegistrationDate()));
365	        owner.setHouseholdSize(householdSize(owner.getHouseholdId()));
366	        owner.setMembershipLevel(membershipLevel(owner));
367	        assignPossibleDuplicate(owner, sharesHousehold);
368	    }
369	
370	    /**
371	     * The membership level to assign a newly created owner and store on it as its
372	     * {@link Owner#getMembershipLevel() membershipLevel}: the owner's own
373	     * {@linkplain Owner#getBaseMembershipLevel() base level} derived from its membershipPoints,
374	     * capped so it cannot exceed one above the current maximum membershipLevel among the owner's
375	     * existing {@linkplain #householdMembers(String) household members}. With no existing household
376	     * member no cap applies and the base level is used as-is. This is the single place the stored
377	     * membership level is derived; it runs during {@link #assignDerivedAttributes(Owner, boolean)},
378	     * after the owner has passed the duplicate and capacity checks and so has its household members
379	     * available to it.
380	     */
381	    private Integer membershipLevel(Owner owner) {
382	        int base = owner.getBaseMembershipLevel();
383	        Collection<Owner> members = householdMembers(owner.getHouseholdId());
384	        if (members.isEmpty()) {
385	            return base;
386	        }
387	        int householdMax = members.stream()
388	            .mapToInt(Owner::getMembershipLevel)
389	            .max()
390	            .getAsInt();
391	        return Math.min(base, householdMax + 1);
392	    }
393	
394	    /**
395	     * Flag a newly created owner as a possible (soft) duplicate. An owner that declares it shares a
396	     * household ({@code sharesHousehold}) is a declared household member, not a suspected duplicate,
397	     * so it is never flagged. Otherwise it is flagged only when it is a soft match of an existing
398	     * owner as determined by {@link #findSoftDuplicate(Owner)}. When such an owner exists the new owner is flagged with
399	     * {@code possibleDuplicate = true} and {@code possibleDuplicateOf} set to that owner's id;
400	     * otherwise {@code possibleDuplicate = false} and no matching id is recorded.
401	     */
402	    private void assignPossibleDuplicate(Owner owner, boolean sharesHousehold) {
403	        Owner match = sharesHousehold ? null : findSoftDuplicate(owner);
404	        owner.setPossibleDuplicate(match != null);
405	        owner.setPossibleDuplicateOf(match == null ? null : match.getId());
406	    }
407	
408	    /**
409	     * The owners a newly created owner is checked against by the duplicate and identity rules:
410	     * the {@link #householdMembers(String) household} membership and {@link #findSoftDuplicate(Owner)
411	     * soft-duplicate} checks, the {@link #customerCode(Owner) customerCode} de-duplication and the
412	     * {@link #namesakeCount(String, String) namesake} count. This is the single place that scope is
413	     * defined, so every one of those rules considers exactly the same set of owners; it spans every
414	     * owner the clinic holds except those flagged {@linkplain Owner#isDeleted() deleted}, which a
415	     * soft delete retains but excludes from duplicate and identity detection.
416	     */
417	    private Collection<Owner> activeOwners() {
418	        return this.clinicService.findAllOwners().stream()
419	            .filter(owner -> !owner.isDeleted())
420	            .collect(Collectors.toList());
421	    }
422	
423	    /**
424	     * The existing owner this owner softly duplicates, or {@code null} when there is none. A soft
425	     * match is an existing owner that shares this owner's lastName (compared case-insensitively,
426	     * with collapsed whitespace) and its postcode but carries a different telephone; the earliest
427	     * such owner (by id) is returned. A postcode is required for a soft match, so an owner without a
428	     * postcode never matches.
429	     */
430	    private Owner findSoftDuplicate(Owner owner) {
431	        if (owner.getPostcode() == null) {
432	            return null;
433	        }
434	        String candidateLastName = normalizeName(owner.getLastName());
435	        return activeOwners().stream()
436	            .filter(existing -> owner.getPostcode().equals(existing.getPostcode()))
437	            .filter(existing -> normalizeName(existing.getLastName()).equals(candidateLastName))
438	            .filter(existing -> !owner.getTelephone().equals(existing.getTelephone()))
439	            .min(Comparator.comparingInt(Owner::getId))
440	            .orElse(null);
441	    }
442	
443	    /**
444	     * Build the customer code for a newly created owner, formatted {@code '<REGION>-<HASH8>'}
445	     * where REGION is the region derived from the owner's postcode (or {@link Owner#UNKNOWN_REGION}
446	     * when the postcode is absent or maps to no known region) and HASH8 is the first 8 upper-case
447	     * hex characters of the SHA-256 of the normalized (E.164) telephone concatenated with the
448	     * lastName (e.g. {@code 'NSW-3C1A9F2B'}). This is the single source of the owner's identity:
449	     * every value built from the customer code (the membership number and its check digit) and the
450	     * owner's locality are derived from it.
451	     *
452	     * <p>When the computed code collides with an existing owner's {@code customerCode}, a
453	     * {@code '-<n>'} suffix is appended with the smallest {@code n} of 2 or more that makes the code
454	     * unique, and the de-duplicated code is returned.
455	     */
456	    private String customerCode(Owner owner) {
457	        String region = owner.getRegion() != null ? owner.getRegion() : Owner.UNKNOWN_REGION;
458	        String hash8 = shaHexUpper(owner.getTelephone() + owner.getLastName()).substring(0, 8);
459	        String base = region + "-" + hash8;
460	
461	        Set<String> existingCodes = activeOwners().stream()
462	            .map(Owner::getCustomerCode)
463	            .filter(Objects::nonNull)
464	            .collect(Collectors.toSet());
465	
466	        if (!existingCodes.contains(base)) {
467	            return base;
468	        }
469	        int n = 2;
470	        while (existingCodes.contains(base + "-" + n)) {
471	            n++;
472	        }
473	        return base + "-" + n;
474	    }
475	
476	    /**
477	     * Whether the per-day owner creation limit has been reached for the given business day, i.e.
478	     * 100 or more owners already carry that {@code registrationDate}. The day is the adjusted
479	     * (business-day) registration date of the owner being created, so owners are counted per
480	     * business day. When true, a new owner must be rejected with {@code 429 Too Many Requests}.
481	     */
482	    private boolean isDailyLimitReached(LocalDate day) {
483	        long count = this.clinicService.findAllOwners().stream()
484	            .filter(existing -> day.equals(existing.getRegistrationDate()))
485	            .count();
486	        return count >= 100;
487	    }
488	
489	    /**
490	     * Whether creating this owner pushes the day's total past the bulk-signup threshold, i.e.
491	     * more than 80 owners have already been created for the given business day. Counts the owners
492	     * already carrying that {@code registrationDate} (the same accumulation as the daily-limit
493	     * rule); when that count exceeds 80 the newly created owner is flagged with a bulk-signup
494	     * warning.
495	     */
496	    private boolean isBulkSignup(LocalDate day) {
497	        long count = this.clinicService.findAllOwners().stream()
498	            .filter(existing -> day.equals(existing.getRegistrationDate()))
499	            .count();
500	        return count > 80;
501	    }
502	
503	    /**
504	     * Roll a registration date forward onto a business day: when it falls on a Saturday, Sunday or a
505	     * listed public holiday, advance it to the next non-holiday weekday; an ordinary weekday is
506	     * returned unchanged.
507	     */
508	    private LocalDate toBusinessDay(LocalDate date) {
509	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY
510	            || date.getDayOfWeek() == DayOfWeek.SUNDAY
511	            || PUBLIC_HOLIDAYS.contains(date)) {
512	            date = date.plusDays(1);
513	        }
514	        return date;
515	    }
516	
517	    /**
518	     * Whether the given city has reached its owner capacity, i.e. it already contains 50 or
519	     * more owners. Cities are compared case-insensitively.
520	     */
521	    private boolean isCityAtCapacity(String city) {
522	        long count = this.clinicService.findAllOwners().stream()
523	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
524	            .count();
525	        return count >= 50;
526	    }
527	
528	    /**
529	     * The number of existing owners that already share the given firstName and lastName,
530	     * compared case-insensitively (and with surrounding whitespace trimmed and internal
531	     * whitespace runs collapsed). Counted over the owners present before this create.
532	     */
533	    private int namesakeCount(String firstName, String lastName) {
534	        String candidateFirstName = normalizeName(firstName);
535	        String candidateLastName = normalizeName(lastName);
536	        return (int) activeOwners().stream()
537	            .filter(existing -> normalizeName(existing.getFirstName()).equals(candidateFirstName)
538	                && normalizeName(existing.getLastName()).equals(candidateLastName))
539	            .count();
540	    }
541	
542	    /**
543	     * The number of members in this owner's household after this create: the count of existing
544	     * owners already carrying the same non-null {@code householdId} plus one for the owner being
545	     * created. An owner with no household ({@code householdId == null}) is a household of one.
546	     * Owners sharing a household are matched by their assigned {@code householdId}, so the count
547	     * does not depend on the order in which household members were created.
548	     */
549	    private int householdSize(String householdId) {
550	        if (householdId == null) {
551	            return 1;
552	        }
553	        long existing = this.clinicService.findAllOwners().stream()
554	            .filter(other -> householdId.equals(other.getHouseholdId()))
555	            .count();
556	        return (int) existing + 1;
557	    }
558	
559	    /**
560	     * Convert a raw telephone input to its E.164 representation, or {@code null} if it
561	     * cannot form a valid E.164 number.
562	     *
563	     * <p>A leading '+' and country code are kept when present; otherwise country code
564	     * '+61' is assumed and a single leading '0' is dropped from the national digits.
565	     * Spaces, dashes and brackets (indeed any non-digit) are stripped. The result must
566	     * carry 8 to 15 digits after the '+', and — for a recognised country calling code —
567	     * exactly the national-digit count that code requires (see
568	     * {@link Owner#hasValidNationalLength}); otherwise it is rejected as invalid.
569	     */
570	    private String toE164(String telephone) {
571	        if (telephone == null) {
572	            return null;
573	        }
574	        boolean hasCountryCode = telephone.trim().startsWith("+");
575	        String digits = telephone.replaceAll("\\D", "");
576	        String e164;
577	        if (hasCountryCode) {
578	            e164 = digits;
579	        } else {
580	            if (digits.startsWith("0")) {
581	                digits = digits.substring(1);
582	            }
583	            e164 = "61" + digits;
584	        }
585	        if (e164.length() < 8 || e164.length() > 15) {
586	            return null;
587	        }
588	        if (!Owner.hasValidNationalLength(e164)) {
589	            return null;
590	        }
591	        return "+" + e164;
592	    }
593	
594	    /**
595	     * The existing owners already registered in the household identified by {@code householdId}: the
596	     * {@linkplain #activeOwners() active owners} carrying that same non-null householdId. The owner
597	     * being created is not yet persisted, so it is never among them, and a {@code null} householdId
598	     * (an owner with no household) yields an empty collection. This is the single source of a
599	     * household's existing membership, shared by every rule keyed by an owner's household (the
600	     * {@link #membershipLevel(Owner) membership-level} derivation) so the set is never re-derived
601	     * elsewhere; like the other identity rules it ignores {@linkplain Owner#isDeleted() deleted}
602	     * owners.
603	     */
604	    private Collection<Owner> householdMembers(String householdId) {
605	        if (householdId == null) {
606	            return List.of();
607	        }
608	        return activeOwners().stream()
609	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
610	            .collect(Collectors.toList());
611	    }
612	
613	    /**
614	     * Normalize an owner's name for household comparison: trim, collapse internal whitespace runs
615	     * to a single space and lower-case. A null value normalizes to the empty string.
616	     */
617	    private String normalizeName(String value) {
618	        if (value == null) {
619	            return "";
620	        }
621	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
622	    }
623	
624	    /**
625	     * A stable shared identifier for the household an owner belongs to, derived deterministically
626	     * from its lastName and postcode. The lastName is normalized (case-insensitive,
627	     * whitespace-collapsed) before hashing, so every owner sharing the same lastName and postcode is
628	     * assigned the same value regardless of the order in which they are created. Formatted as the
629	     * first 12 upper-case hex characters of the SHA-256 of {@code '<normalizedLastName>|<postcode>'}
630	     * (an absent postcode contributes the empty string).
631	     */
632	    private String householdId(Owner owner) {
633	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
634	        String key = normalizeName(owner.getLastName()) + "|" + postcode;
635	        return shaHexUpper(key).substring(0, 12);
636	    }
637	
638	    /**
639	     * The SHA-256 digest of {@code input}'s UTF-8 bytes, rendered as an upper-case hexadecimal
640	     * string (two hex characters per digest byte, so 64 characters in all). This is the single
641	     * place the hashing-and-hex-encoding is performed; callers that need a shorter opaque token
642	     * take a prefix of the result (e.g. {@link #householdId} keeps the first 12 characters and
643	     * {@link #customerCode} keeps the first 8).
644	     */
645	    private String shaHexUpper(String input) {
646	        try {
647	            byte[] digest = MessageDigest.getInstance("SHA-256")
648	                .digest(input.getBytes(StandardCharsets.UTF_8));
649	            StringBuilder sb = new StringBuilder(digest.length * 2);
650	            for (byte b : digest) {
651	                sb.append(String.format("%02x", b));
652	            }
653	            return sb.toString().toUpperCase();
654	        }
655	        catch (NoSuchAlgorithmException e) {
656	            throw new IllegalStateException("SHA-256 not available", e);
657	        }
658	    }
659	
660	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
661	    @Override
662	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
663	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
664	        if (currentOwner == null) {
665	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
666	        }
667	        currentOwner.setAddress(ownerFieldsDto.getAddress());
668	        currentOwner.setCity(ownerFieldsDto.getCity());
669	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
670	        currentOwner.setLastName(ownerFieldsDto.getLastName());
671	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
672	        this.clinicService.saveOwner(currentOwner);
673	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
674	    }
675	
676	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
677	    @Transactional
678	    @Override
679	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
680	        Owner owner = this.clinicService.findOwnerById(ownerId);
681	        if (owner == null) {
682	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
683	        }
684	        this.clinicService.deleteOwner(owner);
685	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
686	    }
687	
688	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
689	    @Override
690	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
691	        Owner owner = this.clinicService.findOwnerById(ownerId);
692	        if (owner == null) {
693	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
694	        }
695	        HttpHeaders headers = new HttpHeaders();
696	        Pet pet = petMapper.toPet(petFieldsDto);
697	        owner.setId(ownerId);
698	        pet.setOwner(owner);
699	        pet.getType().setName(null);
700	        this.clinicService.savePet(pet);
701	        PetDto petDto = petMapper.toPetDto(pet);
702	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
703	            .buildAndExpand(pet.getId()).toUri());
704	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
705	    }
706	
707	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
708	    @Override
709	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
710	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
711	        if (currentOwner != null) {
712	            Pet currentPet = this.clinicService.findPetById(petId);
713	            if (currentPet != null) {
714	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
715	                currentPet.setName(petFieldsDto.getName());
716	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
717	                this.clinicService.savePet(currentPet);
718	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
719	            }
720	        }
721	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
722	    }
723	
724	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
725	    @Override
726	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
727	        HttpHeaders headers = new HttpHeaders();
728	        Visit visit = visitMapper.toVisit(visitFieldsDto);
729	        Pet pet = new Pet();
730	        pet.setId(petId);
731	        visit.setPet(pet);
732	        this.clinicService.saveVisit(visit);
733	        VisitDto visitDto = visitMapper.toVisitDto(visit);
734	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
735	            .buildAndExpand(visit.getId()).toUri());
736	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
737	    }
738	
739	
740	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
741	    @Override
742	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
743	        Owner owner = this.clinicService.findOwnerById(ownerId);
744	        if (owner != null) {
745	            Pet pet = owner.getPet(petId);
746	            if (pet != null) {
747	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
748	            }
749	        }
750	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
751	    }
752	}
